'use strict';
const labels={ended:'Confirmed termination',reported:'Reported decision · unverified',effort:'Reported citizen effort'};
const colors={ended:'#158463',reported:'#d69835',effort:'#8552c8'};
const el=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
function node(tag,attrs={}){const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n}
function html(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function link(d){return `<a class="source-link" href="${html(d.url)}" target="_blank" rel="noopener noreferrer">${html(d.source)} ↗</a>`}
function project(lon,lat){return [(lon+84.5)*111,(36.7-lat)*151+40]}
let records=[],markers=[];
function select(d){el('detail').innerHTML=`<span class="badge ${d.status}">${labels[d.status]}</span><h3>${html(d.name)}</h3><div class="meta">${d.scope} program · ${d.date}</div><p>${html(d.note)}</p>${link(d)}<p class="meta">Source reviewed November 6, 2026</p>${d.campaignUrl ? '<a class="button" href="'+html(d.campaignUrl)+'">Visit '+html(d.name)+' campaign ↗</a>' : d.name==='Angier'?'<a class="button" href="https://angier.nomoreflock.org">Visit Angier campaign ↗</a>':''}`;markers.forEach(({n,item})=>n.setAttribute('r',item===d?9:6.5))}
function renderList(){const query=el('search').value.trim().toLowerCase(),status=el('status').value;const rows=records.filter(d=>(status==='all'||d.status===status)&&(d.name+' '+d.scope).toLowerCase().includes(query)).sort((a,b)=>a.name.localeCompare(b.name));el('results').textContent=`${rows.length} jurisdictions shown · Updated November 6, 2026`;el('directory').innerHTML=rows.map(d=>`<tr><td>${html(d.name)}<small>${d.scope} program</small>${d.campaignUrl ? '<a href="'+html(d.campaignUrl)+'">Community page ↗</a>' : ''}</td><td><span class="badge ${d.status}">${labels[d.status]}</span></td><td>${d.date}</td><td>${link(d)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No jurisdictions match your search.</td></tr>'}
(async()=>{try{const [dr,gr]=await Promise.all([fetch('data.json?v=20261106-review1', {cache:'no-store'}),fetch('counties.json')]);if(!dr.ok||!gr.ok)throw Error('Unable to load map data');records=await dr.json();const geo=await gr.json();const svg=el('state-map');const counties=node('g');geo.features.forEach(f=>{const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;const path=node('path',{class:'county',d:polys.map(poly=>poly.map(ring=>ring.map((c,i)=>(i?'L':'M')+project(c[0],c[1]).map(v=>v.toFixed(2)).join(',')).join(' ')+'Z').join(' ')).join(' ')});const title=node('title');title.textContent='County boundary · context only';path.append(title);counties.append(path)});svg.append(counties);const group=node('g');records.forEach(d=>{const [x,y]=project(d.lon,d.lat);const n=node('circle',{cx:x,cy:y,r:6.5,fill:colors[d.status],class:'marker',tabindex:0,role:'button','aria-label':`${d.name}: ${labels[d.status]}`});const title=node('title');title.textContent=d.name+' · '+labels[d.status];n.append(title);n.addEventListener('click',()=>select(d));n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(d)}});group.append(n);markers.push({n,item:d})});svg.append(group);const [ax,ay]=project(-78.739,35.507);const label=node('text',{x:ax+13,y:ay-10,fill:'#6036a3','font-size':14,'font-weight':750});label.textContent='ANGIER';svg.append(label);['ended','reported'].forEach(s=>el(s+'-count').textContent=records.filter(d=>d.status===s).length);el('effort-count').textContent=records.filter(d=>d.hasCitizenEffort).length;el('decisions-list').innerHTML=records.filter(d=>d.status==='ended').map(d=>`<article class="card"><span class="badge">Confirmed termination</span><h3>${html(d.name)}</h3><div class="meta">${d.scope} · ${d.date}</div><p>${html(d.note)}</p>${link(d)}</article>`).join('');el('source-list').innerHTML=records.filter(d=>d.status==='ended').map(d=>`<li>${d.name}: ${link(d)}</li>`).join('');el('city-cards').innerHTML=records.filter(d=>d.campaignUrl).sort((a,b)=>a.name.localeCompare(b.name)).map(d=>`<article class="city-card"><span class="eyebrow">${html(d.county || 'North Carolina')} · NC</span><h3>${html(d.name)}</h3><p>${html(d.campaignSummary || 'Explore the local petition and community evidence.')}</p><a class="button" href="${html(d.campaignUrl)}">Visit ${html(d.name)} community ↗</a><span class="city-address">${html(d.campaignUrl.replace('https://',''))}</span></article>`).join('') + '<article class="city-card"><span class="eyebrow">EVERY CITY · EVERY VOICE</span><h3>Other City</h3><p>Don’t see your community? Register your interest and contact details for future local organizing. No automatic emails or official notifications.</p><a class="button" href="https://no-more-flock-other-city.lanternprotocol.chatgpt.site/">Make my voice heard ↗</a><span class="city-address">Private interest register · Separate from city petitions</span></article>';select(records.find(d=>d.name==='Angier'));renderList();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const f=b.dataset.filter;markers.forEach(({n,item})=>{const show=f==='all'||item.status===f;n.style.display=show?'':'none';n.setAttribute('tabindex',show?'0':'-1')});el('status').value=f;renderList();const first=records.find(d=>f==='all'||d.status===f);if(first)select(first)}));el('search').addEventListener('input',renderList);el('status').addEventListener('change',renderList)}catch(e){el('detail').textContent='Map data could not load. Please reload, or follow the source links in the research notes.';el('results').textContent='Directory unavailable. Community roundup: reddit.com/r/DeFlockNC.';console.error(e)}})();
